// Calibration view: pure helpers, kit/provenance logic, peak assignment, reports, and the full bead pipeline on the
// synthetic CytoFLEX-nano-like files in /home/claude/testdata/nano (generated by the calibration UI test generator).
import { existsSync, readFileSync } from 'fs';
import { getBeadKit } from '../src/core/beads';
import { parseFcs } from '../src/core/fcs';
import { findBeadPeaks, fitMesf } from '../src/core/mesf';
import { riWater } from '../src/core/mie';
import { apertureCrossSections, buildSizeCurve, EV_MODEL, fitCollectionAngle, scatterToDiameter, type ScatterSetup } from '../src/core/scattercal';
import { assignPeaks, chanFromKit, guessKit, guessSizeKit, kitShort, rowsFromKit, valuesSource } from '../src/ui/calib/logic';
import { mesfReportCsv, mesfReportText, sizeReportCsv, sizeReportText } from '../src/ui/calib/report';
import {
  csvLine,
  decadeLogScale,
  fmtNum,
  fmtPct,
  fromParticleModel,
  guessFluor,
  isVioletSsc,
  kitName,
  pickScatterChannel,
  positiveLogScale,
  positiveOnly,
  toParticleModel,
  wavelengthForChannel,
  type MesfDef,
  type SizeDef,
} from '../src/ui/calib/util';

const NANO = '/home/claude/testdata/nano';
const HAVE_NANO = ['nanoViS_Low_VSSC.fcs', 'nanoViS_High_VSSC.fcs', 'EV_sample_VSSC.fcs', 'MESF_QuantumFITC5_synthetic.fcs'].every((f) => existsSync(`${NANO}/${f}`));

function load(f: string) {
  const b = readFileSync(`${NANO}/${f}`);
  return parseFcs(b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength));
}
function col(ds: ReturnType<typeof parseFcs>, name: string): Float32Array {
  return ds.data[ds.channels.findIndex((c) => c.name === name)];
}

describe('calibration view helpers', () => {
  it('formats numbers without locale surprises', () => {
    expect(fmtNum(122045.4)).toBe('122,045');
    expect(fmtNum(0.0036516)).toBe('0.003652');
    expect(fmtNum(NaN)).toBe('n/a');
    expect(fmtNum(2.5e-5)).toBe('2.500e-5');
    expect(fmtPct(-0.12)).toBe('-0.1 %');
    expect(fmtPct(3)).toBe('+3.0 %');
    expect(csvLine(['a,b', 1.23456789, null, 'x"y'])).toBe('"a,b",1.23457,,"x""y"');
  });

  it('picks a violet SSC channel and its wavelength', () => {
    expect(pickScatterChannel([{ name: 'FSC-A' }, { name: 'SSC-A' }, { name: 'VSSC1-A' }, { name: 'VSSC2-A' }, { name: 'FITC-A' }])).toBe('VSSC1-A');
    expect(pickScatterChannel([{ name: 'FSC-A' }, { name: 'SSC-H' }, { name: 'SSC-A' }])).toBe('SSC-A');
    expect(pickScatterChannel([{ name: 'FSC-A' }, { name: 'SSC_1-A' }, { name: 'SSC-A' }])).toBe('SSC_1-A');
    expect(pickScatterChannel([{ name: 'B1-A', label: 'FITC' }])).toBeNull();
    expect(isVioletSsc('Violet SSC-A')).toBe(true);
    expect(isVioletSsc('SSC-A')).toBe(false);
    expect(wavelengthForChannel('VSSC-A')).toBe(405);
    expect(wavelengthForChannel('BSSC-A')).toBe(488);
    expect(wavelengthForChannel('SSC-A')).toBe(488);
    expect(wavelengthForChannel('YSSC-A')).toBe(561);
    expect(wavelengthForChannel('RSSC-A')).toBe(638);
  });

  it('matches kit fluorochromes to channels as whole tokens', () => {
    const rcp = getBeadKit('spherotech-rcp-30-5a')!;
    expect(guessFluor(rcp, 'FITC-A')).toBe('FITC');
    expect(guessFluor(rcp, 'PE-A')).toBe('PE');
    expect(guessFluor(rcp, 'PE-Cy5-A')).toBe('PE-Cy5');
    expect(guessFluor(rcp, 'B1-A', 'FITC')).toBe('FITC');
    expect(guessFluor(rcp, 'APC-Cy7-A')).toBe('');
    expect(guessFluor(getBeadKit('bd-quantibrite-pe')!, 'PE-Cy7-A')).toBe('PE'); // single-channel kit: its only fluorochrome
  });

  it('builds log display scales from data', () => {
    const v = Float32Array.from([-5, 0, 10, 100, 1000, 10000]);
    expect(positiveOnly(v).length).toBe(4);
    const s = positiveLogScale(positiveOnly(v));
    expect(s.type).toBe('log');
    expect(decadeLogScale(35, 6e5)).toEqual({ type: 'log', min: 10, max: 1e6 });
  });

  it('round-trips particle models', () => {
    for (const m of [toParticleModel({ kind: 'ev', core: 1.38, shell: 1.48, shellNm: 5 }), toParticleModel({ kind: 'sphere', preset: 'virus', n: 1.47 }), toParticleModel({ kind: 'sphere', preset: 'polystyrene', n: 1.59 })]) {
      expect(toParticleModel(fromParticleModel(m))).toEqual(m);
    }
    expect(kitName(getBeadKit('beckman-nanovis-low')!)).toBe('nanoViS Nanoscale Sizing Standards: Low');
  });
});

describe('MESF kit values and provenance', () => {
  it('loads example values and reports them as examples until the user replaces them all', () => {
    const rcp = getBeadKit('spherotech-rcp-30-5a')!;
    const c = chanFromKit(rcp, { customLabels: [] }, 'FITC-A', '');
    expect(c.fluor).toBe('FITC');
    expect(c.unit).toBe('MEFL');
    expect(c.refs).toEqual([0, 792, 2079, 6588, 16471, 47497, 137049, 271647]);
    expect(valuesSource(rcp, c)).toBe('kit-example');
    const partly = { ...c, edited: c.edited.map((_, i) => i === 2) };
    expect(valuesSource(rcp, partly)).toBe('mixed');
    const all = { ...c, edited: c.edited.map((_, i) => i > 0) }; // blank needs no entry
    expect(valuesSource(rcp, all)).toBe('user');
    const pecy5 = chanFromKit(rcp, { customLabels: [] }, 'PE-Cy5-A', '');
    expect(pecy5.unit).toBe('MEPCY');
    expect(pecy5.refs.slice(1).every((v) => v === null)).toBe(true);
  });
  it('uses templates and custom beads', () => {
    const q = getBeadKit('bangs-quantum-mesf-555')!;
    const c = chanFromKit(q, { customLabels: [] }, 'FITC-A', '');
    expect(c.refs).toEqual([0, null, null, null, null, null]);
    expect(c.unit).toBe('MESF');
    const cu = chanFromKit(undefined, { customLabels: ['Blank', 'P1', 'P2'] }, 'PE-A', '');
    expect(cu.refs).toEqual([0, null, null]);
    expect(valuesSource(undefined, cu)).toBe('user');
    expect(guessKit('MESF_QuantumFITC5_synthetic')).toBe('bangs-quantum-mesf-555');
    expect(guessKit('Rainbow_RCP-30-5A')).toBe('spherotech-rcp-30-5a');
    expect(guessKit('sample 3')).toBe('custom');
  });
});

describe('size bead peak assignment', () => {
  const beads = (n: number) => Array.from({ length: n }, () => ({ use: true, assign: null as number | null }));
  it('assigns from the brightest bead down, with the noise as the lowest peak', () => {
    const sig = [0.44, 24.8, 124.7, 446]; // 40, 80, 108, 142 nm
    expect(assignPeaks(beads(4), sig, 5, true)).toEqual({ assign: [1, 2, 3, 4], noisePeak: 0, conflicts: [] });
    // 40 nm merged with the noise: 4 peaks found
    expect(assignPeaks(beads(4), sig, 4, true).assign).toEqual([-1, 1, 2, 3]);
    // without a noise population
    expect(assignPeaks(beads(4), sig, 4, false)).toEqual({ assign: [0, 1, 2, 3], noisePeak: -1, conflicts: [] });
    // excluded bead and order by signal, not by list order
    const b = beads(3);
    b[0].use = false;
    expect(assignPeaks(b, [5, 300, 20], 3, true).assign).toEqual([-1, 2, 1]);
  });
  it('honours manual assignments and reports conflicts', () => {
    const b = beads(4);
    b[0].assign = 0; // user: the 40 nm bead is the lowest peak, not noise
    const r = assignPeaks(b, [1, 2, 3, 4], 5, true);
    expect(r.assign).toEqual([0, 2, 3, 4]);
    expect(r.noisePeak).toBe(-1);
    b[1].assign = 3;
    expect(assignPeaks(b, [1, 2, 3, 4], 5, true).conflicts).toEqual([[3, 1, 2]]);
  });
  it('knows the size kits', () => {
    expect(guessSizeKit('nanoViS_Low_VSSC')).toBe('beckman-nanovis-low');
    expect(guessSizeKit('nanoViS High 2026')).toBe('beckman-nanovis-high');
    expect(guessSizeKit('ApogeeMix 1527')).toBe('apogee-1527');
    expect(guessSizeKit('EV_sample')).toBeNull();
    expect(kitShort(getBeadKit('beckman-nanovis-high'))).toBe('High');
    expect(rowsFromKit(getBeadKit('beckman-nanovis-low')).map((r) => r.diameterNm)).toEqual([40, 80, 108, 142]);
  });
});

describe('calibration reports', () => {
  it('MESF report states kit, lot, regression and example status', () => {
    const peaks = [300, 3375, 13500, 54000, 202500, 810000];
    const refs = [0, 2500, 10000, 40000, 150000, 600000];
    const fit = fitMesf(peaks, refs);
    const def: MesfDef = {
      id: 'm1',
      kind: 'mesf',
      name: 'FITC-A MESF',
      channel: 'FITC-A',
      unit: 'MESF',
      outputs: [{ name: 'FITC-A MESF', range: 1e7 }],
      created: '2026-10-11T10:00:00Z',
      fit: { method: fit.method, slope: fit.slope, intercept: fit.intercept, r2: fit.r2 },
      beads: { sampleName: 'beads', kitId: 'bangs-quantum-mesf-555', lot: 'L123', medians: peaks, refs, threshold: 500, blankMedian: 300, blankRsd: 100, labels: ['Blank', 'L1', 'L2', 'L3', 'L4', 'L5'], valuesSource: 'user' },
    };
    const txt = mesfReportText(def);
    expect(txt).toContain('lot L123');
    expect(txt).toContain('Quantum FITC-5 MESF');
    expect(txt).toContain(`log10(MESF) = ${fit.intercept.toFixed(4)} + ${fit.slope.toFixed(4)} x log10(MFI)`);
    expect(txt).toContain('entered by the user');
    expect(txt).toContain('500 MFI = 500 MESF');
    expect(txt).not.toMatch(/[—]/);
    const csv = mesfReportCsv(def);
    expect(csv.split('\r\n').filter((l) => /^L\d,/.test(l))).toHaveLength(5);
    expect(csv).toContain('Blank,0,300,,,blank');
    const ex = mesfReportText({ ...def, beads: { ...def.beads!, valuesSource: 'kit-example' } });
    expect(ex).toContain('EXAMPLE values');
  });

  it('size report states geometry, factor, model, range and beads', () => {
    const setup: ScatterSetup = { wavelengthNm: 405, nMedium: riWater(405), geometry: { thetaDeg: 90, phiDeg: 90, halfAngleDeg: 53.2 } };
    const kit = getBeadKit('beckman-nanovis-low')!;
    const beads = kit.beads!.map((b) => ({ diameterNm: b.diameterNm, ri: b.ri, label: b.label }));
    const meas = beads.map((b) => apertureCrossSections({ kind: 'sphere', ri: b.ri }, [b.diameterNm], setup)[0] / 0.00365);
    const fit = fitCollectionAngle(beads, meas, { wavelengthNm: 405, nMedium: setup.nMedium, method: 'cv' });
    const curve = buildSizeCurve(EV_MODEL, fit.setup);
    const def: SizeDef = {
      id: 's1',
      kind: 'size',
      name: 'VSSC1-A size',
      channel: 'VSSC1-A',
      nm2PerAu: fit.nm2PerAu,
      setup: fit.setup,
      model: EV_MODEL,
      outputs: [{ name: 'VSSC1-A diameter (nm)', range: 1500 }],
      fit: {
        method: fit.method,
        halfAngleDeg: fit.halfAngleDeg,
        r2Log: fit.r2Log,
        cvPct: fit.cvPct,
        beads: fit.beads.map((b) => ({ name: b.label, diameterNm: b.diameterNm, measured: b.measured, residualPct: b.residualPct })),
        validRangeNm: curve.validRangeNm,
        validSigmaNm2: curve.validSigmaNm2,
        setups: [{ sampleName: 'low', kitId: kit.id, kitName: kitName(kit), beads: kit.beads!.map((b, i) => ({ label: b.label!, diameterNm: b.diameterNm, ri: b.ri, use: true, assign: null, measured: meas[i] })) }],
        sizedBeads: fit.beads.map((b) => ({ label: b.label, diameterNm: b.diameterNm, sizedNm: b.sizedNm, sizeErrorPct: b.sizeErrorPct, predicted: b.predicted, sigmaNm2: b.sigmaNm2 })),
      },
    };
    expect(fit.halfAngleDeg).toBeCloseTo(53.2, 1);
    const txt = sizeReportText(def);
    expect(txt).toContain('collection half-angle 53.2°');
    expect(txt).toContain('0.00365 nm² per a.u.');
    expect(txt).toContain('core-shell sphere');
    expect(txt).toContain('40 nm (RI 1.6268)');
    expect(txt).not.toMatch(/[—–]/);
    const csv = sizeReportCsv(def);
    expect(csv).toContain('Calibration factor (nm2 per a.u.),0.00365');
    expect(csv.split('\r\n').filter((l) => l.startsWith('low,'))).toHaveLength(4);
  });
});

describe.skipIf(!HAVE_NANO)('synthetic CytoFLEX nano files: UI pipeline', () => {
  it('recovers the collection half-angle, factor and bead sizes from nanoViS Low + High', () => {
    const setup: ScatterSetup = { wavelengthNm: 405, nMedium: riWater(405), geometry: { thetaDeg: 90, phiDeg: 90, halfAngleDeg: 53.2 } };
    const beads: { diameterNm: number; ri: never; label: string }[] = [];
    const meas: number[] = [];
    for (const [file, kitId] of [
      ['nanoViS_Low_VSSC.fcs', 'beckman-nanovis-low'],
      ['nanoViS_High_VSSC.fcs', 'beckman-nanovis-high'],
    ] as const) {
      const v = positiveOnly(col(load(file), 'VSSC1-A'));
      const rows = rowsFromKit(getBeadKit(kitId));
      const det = findBeadPeaks(v, rows.length + 1, { scale: positiveLogScale(v) });
      expect(det.ok).toBe(true);
      const sig = rows.map((b) => apertureCrossSections({ kind: 'sphere', ri: b.ri }, [b.diameterNm], setup)[0]);
      const a = assignPeaks(rows, sig, det.peaks.length, true);
      expect(a.noisePeak).toBe(0);
      expect(det.peaks[0].median).toBeGreaterThan(20);
      expect(det.peaks[0].median).toBeLessThan(40);
      rows.forEach((b, i) => {
        beads.push({ diameterNm: b.diameterNm, ri: b.ri as never, label: b.label });
        meas.push(det.peaks[a.assign[i]].median);
      });
    }
    const fit = fitCollectionAngle(beads, meas, { wavelengthNm: 405, nMedium: setup.nMedium, method: 'cv' });
    expect(Math.abs(fit.halfAngleDeg - 53.2)).toBeLessThan(0.5);
    expect(Math.abs(fit.nm2PerAu / 0.00365 - 1)).toBeLessThan(0.02);
    for (const b of fit.beads) expect(Math.abs(b.sizeErrorPct)).toBeLessThan(2);
    // EV sample: diameters of the EV events (above the noise) in the generated range
    const ev = col(load('EV_sample_VSSC.fcs'), 'VSSC1-A');
    const d = scatterToDiameter(buildSizeCurve(EV_MODEL, fit.setup), ev, { nm2PerAu: fit.nm2PerAu });
    const big = Array.from(d).filter((x) => x > 80).sort((x, y) => x - y);
    expect(big.length).toBeGreaterThan(30000);
    expect(big[Math.floor(big.length / 2)]).toBeGreaterThan(110);
    expect(big[Math.floor(big.length / 2)]).toBeLessThan(160);
    // generated diameters end at 400 nm (4 % signal noise widens the top a little)
    expect(big[Math.floor(big.length * 0.999)]).toBeLessThan(420);
  });

  it('gives an MESF slope of about 1 on the Quantum FITC-5 file', () => {
    const v = col(load('MESF_QuantumFITC5_synthetic.fcs'), 'FITC-A');
    const det = findBeadPeaks(v, 6);
    expect(det.ok).toBe(true);
    const fit = fitMesf(det.peaks, [0, 2500, 10000, 40000, 150000, 600000]);
    expect(Math.abs(fit.slope - 1)).toBeLessThan(0.01);
    expect(fit.r2).toBeGreaterThan(0.9999);
    for (const p of fit.points) if (!p.blank) expect(Math.abs(p.residualPct)).toBeLessThan(2);
  });
});
